package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

// Go declarations derived from the DATA DIVISION
type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLeapFlag string = "N" // PIC X len=1 = "N"
var WsQ int64 = 0          // PIC 9(4) len=4 = 0
var WsR4 int64 = 0         // PIC 9(3) len=3 = 0
var WsR100 int64 = 0       // PIC 9(3) len=3 = 0
var WsR400 int64 = 0       // PIC 9(3) len=3 = 0
var WsMaxDay int64 = 0     // PIC 99 len=2 = 0
var WsValid int64 = 0      // PIC 99 len=2 = 0
var WsBadMonth int64 = 0   // PIC 99 len=2 = 0
var WsBadDay int64 = 0     // PIC 99 len=2 = 0

// runtime helpers for file
var curRec DateRec
var dateRecords []DateRec
var dateIdx int

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncVal(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := pow10(digits)
	if v >= 0 {
		return v % mod
	}
	return -((-v) % mod)
}

func fmtPic9(v int64, digits int) string {
	tv := truncVal(v, digits)
	if tv < 0 {
		tv = -tv
	}
	return fmt.Sprintf("%0*d", digits, tv)
}

func parseNum(s string, digits int) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	v, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	_ = digits
	return v
}

func loadDateFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		dateRecords = []DateRec{}
		dateIdx = 0
		return
	}
	defer f.Close()
	dateRecords = []DateRec{}
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		idStr := line[0:4]
		yyyyStr := line[4:8]
		mmStr := line[8:10]
		ddStr := line[10:12]
		rec := DateRec{}
		rec.DtId = idStr
		rec.DtYyyy = truncVal(parseNum(yyyyStr, 4), 4)
		rec.DtMm = truncVal(parseNum(mmStr, 2), 2)
		rec.DtDd = truncVal(parseNum(ddStr, 2), 2)
		dateRecords = append(dateRecords, rec)
	}
	dateIdx = 0
}

// Paragraph functions

func ReadPara() {
	if dateIdx >= len(dateRecords) {
		WsEofFlag = "Y"
	} else {
		curRec = dateRecords[dateIdx]
		dateIdx++
	}
}

func LeapPara() {
	q := curRec.DtYyyy / 4
	r := curRec.DtYyyy % 4
	WsQ = truncVal(q, 4)
	WsR4 = truncVal(r, 3)

	q = curRec.DtYyyy / 100
	r = curRec.DtYyyy % 100
	WsQ = truncVal(q, 4)
	WsR100 = truncVal(r, 3)

	q = curRec.DtYyyy / 400
	r = curRec.DtYyyy % 400
	WsQ = truncVal(q, 4)
	WsR400 = truncVal(r, 3)

	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch curRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = truncVal(29, 2)
		} else {
			WsMaxDay = truncVal(28, 2)
		}
	case 4, 6, 9, 11:
		WsMaxDay = truncVal(30, 2)
	default:
		WsMaxDay = truncVal(31, 2)
	}
}

func ProcessPara() {
	LeapPara()
	if curRec.DtMm < 1 || curRec.DtMm > 12 {
		WsBadMonth = truncVal(WsBadMonth+1, 2)
		line := curRec.DtId + " BAD MONTH " + fmtPic9(curRec.DtMm, 2)
		fmt.Println(line)
	} else {
		DaysPara()
		if curRec.DtDd < 1 || curRec.DtDd > WsMaxDay {
			WsBadDay = truncVal(WsBadDay+1, 2)
			line := curRec.DtId + " BAD DAY " + fmtPic9(curRec.DtDd, 2) + " MAX " + fmtPic9(WsMaxDay, 2)
			fmt.Println(line)
		} else {
			WsValid = truncVal(WsValid+1, 2)
			line := curRec.DtId + " VALID " + fmtPic9(curRec.DtYyyy, 4) + "-" + fmtPic9(curRec.DtMm, 2) + "-" + fmtPic9(curRec.DtDd, 2)
			fmt.Println(line)
		}
	}
	ReadPara()
}

func MainPara() {
	// OPEN INPUT DATE-FILE
	loadDateFile()
	PerformReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE DATE-FILE (implicit)
	line := "VALID: " + fmtPic9(WsValid, 2) + " BAD MONTH: " + fmtPic9(WsBadMonth, 2) + " BAD DAY: " + fmtPic9(WsBadDay, 2)
	fmt.Println(line)
}

func PerformReadPara() { ReadPara() }

func main() {
	MainPara()
}
